    background: #f7f7f7;
    font-style: italic;
}

[dir="rtl"] blockquote {
    border-right: 1px solid #bbb;
    border-left: none;
}

blockquote:before {
    margin-right: 0.2em;
    content: "\201C";
    vertical-align: -0.4em;
    color: #bbb;
    font-size: 3em;
    line-height: 0.1em;
}

[dir="rtl"] blockquote:before {
    margin-right: 0;
    margin-left: 0.2em;
    content: "\201D";
}

blockquote:after {
    content: "\201D";
    vertical-align: -0.45em;
    color: #bbb;
    font-size: 3em;
    line-height: 0.1em;
}

[dir="rtl"] blockquote:after {
    content: "\201C";
}

blockquote>p:first-child {
